# (standalone default, accepted values/constraints, exact effect)
COMMON_CONTROLS = {
    "config": ("None", "Path to a JSON object; underscore keys", "Reads CLI defaults; explicit CLI flags win. Notebook profiles create these JSON files automatically."),
    "text": ("None", "UTF-8 string; exclusive with text_file", "Literal text. All three adapters enforce 10..500 whitespace-delimited words."),
    "text_file": ("None", "UTF-8/UTF-8-BOM file; exclusive with text", "Loads the complete source text. No repetition or clipping to reach a target word count."),
    "n": ("1", "Integer >=1", "Number of output WAVs. The notebook normally makes n=2 per profile/text case."),
    "threads": ("4", "Integer >=1", "CPU inference thread count; does not select a voice or alter desired duration."),
    "device": ("cpu", "cpu, cuda, cuda:INDEX", "Selects inference device. Notebook sets cuda:0 inside each GPU-isolated worker; CUDA index is local to CUDA_VISIBLE_DEVICES."),
    "max_vram_gb": ("5.0", "Finite 0 < value <=5; decimal GB", "Allocator/arena target, not a certified whole-device ceiling. Notebook additionally polls total device usage through NVML."),
    "pause_ms": ("0.0", "Finite >=0 milliseconds", "Inserts exactly round(pause_ms*native_rate/1000) silence samples between final chunks. Adds to predicted and actual duration; does not remove model-generated silence."),
    "edge_fade_ms": ("3.0", "Finite 0..20 milliseconds", "Cosine attenuation at both ends of each chunk, capped at half that chunk. Zero disables it; sample count and timing are unchanged."),
    "gain_db": ("0.0", "Finite -120..120 dB", "Multiplies the final resampled waveform by 10**(gain_db/20). Changes loudness only; excessive positive gain can trigger peak attenuation."),
    "normalize_peak": ("True", "Boolean", "Attenuates the whole recording only if its absolute peak exceeds 0.98. Does not amplify quiet audio, compress dynamics, or alter duration."),
    "estimate_only": ("False", "Boolean", "Loads models and writes the reusable duration preflight/report without synthesizing a WAV. Cold loading is separate from preview latency."),
}

