def _controls_table(model: str) -> str:
    rows = ["| JSON key / CLI flag | Standalone default | Allowed values | Exact effect |",
            "|---|---|---|---|"]
    for key, (default, bounds, effect) in CONTROL_DETAILS[model].items():
        flag = "--" + key.replace("_", "-")
        rows.append(f"| `{key}` / `{flag}` | {default} | {bounds} | {effect} |")
    return "\n".join(rows)


